2	 "nodes": {
3	  "identity": {
4	   "name": "identity",
5	   "tools": [
6	    {
7	     "type": "function",
8	     "config": {
9	      "timeoutMs": 12000,
10	      "maxRetries": 0
11	     },
12	     "function": {
13	      "name": "verify_identity",
14	      "handler": "__function__:api_call",
15	      "parameters": {
16	       "type": "object",
17	       "properties": {
18	        "url": {
19	         "type": "string",
20	         "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/verify_identity"
21	        },
22	        "body": {
23	         "type": "object",
24	         "required": [
25	          "field",
26	          "answer"
27	         ],
28	         "properties": {
29	          "field": {
30	           "enum": [
31	            "date_of_birth",
32	            "phone_last4"
33	           ],
34	           "type": "string",
35	           "default": "{{field}}",
36	           "description": "Which answer this is."
37	          },
38	          "answer": {
39	           "type": "string",
40	           "default": "{{answer}}",
41	           "description": "date_of_birth as YYYY-MM-DD, phone_last4 as four digits."
42	          },
43	          "customer_id": {
44	           "type": "string",
45	           "default": "{{customer_id}}"
46	          }
47	         }
48	        },
49	        "method": {
50	         "type": "string",
51	         "default": "POST"
52	        },
53	        "headers": {
54	         "type": "object",
55	         "properties": {
56	          "Content-Type": {
57	           "type": "string",
58	           "default": "application/json"
59	          }
60	         }
61	        }
62	       }
63	      },
64	      "description": "Check one security answer. Call it once for each answer the customer gives."
65	     }
66	    },
67	    {
68	     "type": "function",
69	     "config": {
70	      "timeoutMs": 10000
71	     },
72	     "function": {
73	      "name": "end_call",
74	      "handler": "__function__:end_call",
75	      "parameters": {
76	       "type": "object",
77	       "properties": {
78	        "message_mode": {
79	         "type": "string",
80	         "default": "none"
81	        },
82	        "interruptible": {
83	         "type": "boolean",
84	         "default": true
85	        },
86	        "trigger_pattern": {
87	         "type": "string",
88	         "default": "Have a good day|have a good day"
89	        },
90	        "trigger_timeout": {
91	         "type": "number",
92	         "default": 3
93	        },
94	        "trigger_pattern_both": {
95	         "type": "string",
96	         "default": "goodbye|bye|have a good day|you too|thank you|thanks|take care"
97	        }
98	       }
99	      },
100	      "description": "Ends the call. You normally do NOT call this: the phrase \"Have a good day.\" ends the call by itself. Call it without any text only if the customer answers after your goodbye."
101	     }
102	    }
103	   ],
